insert into public.diagnostic_questions(id,question_text,category,subcategory,difficulty,option_a,option_b,option_c,option_d,correct_answer,explanation,estimated_time_seconds,active) select id,question_text,category,subcategory,difficulty,option_a,option_b,option_c,option_d,correct_answer,explanation,estimated_time_seconds,true from jsonb_to_recordset($diagnostic$[{"id":"tech2-26","category":"database_technical","subcategory":"Security","question_text":"Why should passwords be hashed with a password-specific algorithm?","options":["To make passwords visible to administrators","To shorten every password to four characters","To remove authentication","To avoid storing recoverable plaintext and resist guessing attacks"],"correct_answer":"D","explanation":"Password hashing stores a one-way verifier with deliberate computational cost.","estimated_time_seconds":60,"difficulty":2,"option_a":"To make passwords visible to administrators","option_b":"To shorten every password to four characters","option_c":"To remove authentication","option_d":"To avoid storing recoverable plaintext and resist guessing attacks"},{"id":"tech2-27","category":"database_technical","subcategory":"Security","question_text":"What is multi-factor authentication?","options":["Using more than one independent category of proof","Entering the same password twice","Sharing one account","Disabling session expiry"],"correct_answer":"A","explanation":"MFA combines independent factors such as knowledge and possession.","estimated_time_seconds":60,"difficulty":2,"option_a":"Using more than one independent category of proof","option_b":"Entering the same password twice","option_c":"Sharing one account","option_d":"Disabling session expiry"},{"id":"tech2-28","category":"database_technical","subcategory":"Security","question_text":"What is SQL injection?","options":["A database backup method","Untrusted input altering the structure of a database query","A CSS rendering issue","A type of image upload"],"correct_answer":"B","explanation":"SQL injection occurs when input is treated as executable query syntax.","estimated_time_seconds":60,"difficulty":3,"option_a":"A database backup method","option_b":"Untrusted input altering the structure of a database query","option_c":"A CSS rendering issue","option_d":"A type of image upload"},{"id":"tech2-29","category":"database_technical","subcategory":"Security","question_text":"What is the safest general way to include user values in SQL?","options":["Concatenate raw input","Disable validation","Use parameterized queries","Store the query in a cookie"],"correct_answer":"C","explanation":"Parameters keep values separate from SQL syntax.","estimated_time_seconds":60,"difficulty":3,"option_a":"Concatenate raw input","option_b":"Disable validation","option_c":"Use parameterized queries","option_d":"Store the query in a cookie"},{"id":"tech2-30","category":"database_technical","subcategory":"Security","question_text":"What does the principle of least privilege require?","options":["Give every user administrator access","Never revoke access","Share credentials across teams","Grant only the permissions needed for the task"],"correct_answer":"D","explanation":"Least privilege limits the impact of mistakes and compromise.","estimated_time_seconds":60,"difficulty":3,"option_a":"Give every user administrator access","option_b":"Never revoke access","option_c":"Share credentials across teams","option_d":"Grant only the permissions needed for the task"},{"id":"tech2-31","category":"database_technical","subcategory":"Databases","question_text":"What is a database transaction?","options":["A group of operations treated as one logical unit","A visual chart","A network cable","A source-code comment"],"correct_answer":"A","explanation":"Transactions group related database changes with defined completion behavior.","estimated_time_seconds":60,"difficulty":1,"option_a":"A group of operations treated as one logical unit","option_b":"A visual chart","option_c":"A network cable","option_d":"A source-code comment"},{"id":"tech2-32","category":"database_technical","subcategory":"Databases","question_text":"Why is a primary key useful?","options":["It formats every date","It uniquely identifies each row","It automatically encrypts a table","It duplicates records"],"correct_answer":"B","explanation":"A primary key supplies stable row identity and uniqueness.","estimated_time_seconds":60,"difficulty":1,"option_a":"It formats every date","option_b":"It uniquely identifies each row","option_c":"It automatically encrypts a table","option_d":"It duplicates records"},{"id":"tech2-33","category":"database_technical","subcategory":"Databases","question_text":"What is a foreign key used for?","options":["Sorting text alphabetically","Compressing a table","Linking a value to a key in another or the same table","Running JavaScript"],"correct_answer":"C","explanation":"Foreign keys express and enforce referential relationships.","estimated_time_seconds":60,"difficulty":2,"option_a":"Sorting text alphabetically","option_b":"Compressing a table","option_c":"Linking a value to a key in another or the same table","option_d":"Running JavaScript"},{"id":"tech2-34","category":"database_technical","subcategory":"Databases","question_text":"Which SQL command reads rows from a table?","options":["INSERT","UPDATE","DROP","SELECT"],"correct_answer":"D","explanation":"SELECT retrieves rows and expressions from relational data.","estimated_time_seconds":60,"difficulty":2,"option_a":"INSERT","option_b":"UPDATE","option_c":"DROP","option_d":"SELECT"},{"id":"tech2-35","category":"database_technical","subcategory":"Databases","question_text":"Which SQL command adds a new row?","options":["INSERT","SELECT","GRANT","ROLLBACK"],"correct_answer":"A","explanation":"INSERT creates new table rows.","estimated_time_seconds":60,"difficulty":2,"option_a":"INSERT","option_b":"SELECT","option_c":"GRANT","option_d":"ROLLBACK"},{"id":"tech2-36","category":"database_technical","subcategory":"Operating Systems","question_text":"What is a process?","options":["A database column","A running instance of a program","A CSS selector","A static text file only"],"correct_answer":"B","explanation":"A process is a program in execution with managed resources.","estimated_time_seconds":60,"difficulty":2,"option_a":"A database column","option_b":"A running instance of a program","option_c":"A CSS selector","option_d":"A static text file only"},{"id":"tech2-37","category":"database_technical","subcategory":"Operating Systems","question_text":"What is a thread?","options":["A database constraint","A network domain","A schedulable execution path within a process","A file extension"],"correct_answer":"C","explanation":"Threads are execution paths that share their process resources.","estimated_time_seconds":60,"difficulty":2,"option_a":"A database constraint","option_b":"A network domain","option_c":"A schedulable execution path within a process","option_d":"A file extension"},{"id":"tech2-38","category":"database_technical","subcategory":"Networking","question_text":"What does an IP address identify?","options":["A database password","A CSS class","A Git commit","A network interface in an IP network"],"correct_answer":"D","explanation":"IP addresses support identifying and routing to network interfaces.","estimated_time_seconds":60,"difficulty":3,"option_a":"A database password","option_b":"A CSS class","option_c":"A Git commit","option_d":"A network interface in an IP network"},{"id":"tech2-39","category":"database_technical","subcategory":"Networking","question_text":"What does DNS commonly translate?","options":["Domain names to network addresses","JavaScript to machine code","Rows to columns","Passwords to plaintext"],"correct_answer":"A","explanation":"DNS resolves human-readable names to records such as IP addresses.","estimated_time_seconds":60,"difficulty":3,"option_a":"Domain names to network addresses","option_b":"JavaScript to machine code","option_c":"Rows to columns","option_d":"Passwords to plaintext"},{"id":"tech2-40","category":"database_technical","subcategory":"Networking","question_text":"What is the role of a router?","options":["Compiling source code","Forwarding packets between networks","Styling a webpage","Creating database tables"],"correct_answer":"B","explanation":"Routers select paths and forward traffic across networks.","estimated_time_seconds":60,"difficulty":3,"option_a":"Compiling source code","option_b":"Forwarding packets between networks","option_c":"Styling a webpage","option_d":"Creating database tables"},{"id":"tech2-41","category":"database_technical","subcategory":"Cloud","question_text":"What does horizontal scaling mean?","options":["Adding more memory to one machine only","Deleting all replicas","Adding more service instances","Reducing availability zones"],"correct_answer":"C","explanation":"Horizontal scaling distributes work across additional instances.","estimated_time_seconds":60,"difficulty":1,"option_a":"Adding more memory to one machine only","option_b":"Deleting all replicas","option_c":"Adding more service instances","option_d":"Reducing availability zones"},{"id":"tech2-42","category":"database_technical","subcategory":"Cloud","question_text":"What is an availability zone?","options":["A programming loop","A database column type","A browser setting","An isolated location within a cloud region"],"correct_answer":"D","explanation":"Zones provide separate failure domains within a region.","estimated_time_seconds":60,"difficulty":1,"option_a":"A programming loop","option_b":"A database column type","option_c":"A browser setting","option_d":"An isolated location within a cloud region"},{"id":"tech2-43","category":"database_technical","subcategory":"DevOps","question_text":"What is continuous integration?","options":["Frequently merging and automatically validating changes","Manually deploying once a year","Disabling tests","Sharing production passwords"],"correct_answer":"A","explanation":"CI validates integrated changes through automated builds and tests.","estimated_time_seconds":60,"difficulty":2,"option_a":"Frequently merging and automatically validating changes","option_b":"Manually deploying once a year","option_c":"Disabling tests","option_d":"Sharing production passwords"},{"id":"tech2-44","category":"database_technical","subcategory":"DevOps","question_text":"What is a deployment rollback?","options":["Deleting all source history","Returning to a previously working release","Adding an untested feature","Changing a username"],"correct_answer":"B","explanation":"Rollback restores an earlier release when a deployment is unhealthy.","estimated_time_seconds":60,"difficulty":2,"option_a":"Deleting all source history","option_b":"Returning to a previously working release","option_c":"Adding an untested feature","option_d":"Changing a username"},{"id":"tech2-45","category":"database_technical","subcategory":"Containers","question_text":"What does a container image contain?","options":["A running database transaction","Only a screenshot","A packaged filesystem and metadata used to start containers","A physical server"],"correct_answer":"C","explanation":"An image is an immutable package used to create container instances.","estimated_time_seconds":60,"difficulty":2,"option_a":"A running database transaction","option_b":"Only a screenshot","option_c":"A packaged filesystem and metadata used to start containers","option_d":"A physical server"},{"id":"tech2-46","category":"database_technical","subcategory":"Containers","question_text":"How does a container differ from a virtual machine?","options":["It cannot run applications","It always includes physical hardware","It has no filesystem","It normally shares the host kernel rather than emulating a complete guest machine"],"correct_answer":"D","explanation":"Containers isolate processes while generally sharing the host kernel.","estimated_time_seconds":60,"difficulty":2,"option_a":"It cannot run applications","option_b":"It always includes physical hardware","option_c":"It has no filesystem","option_d":"It normally shares the host kernel rather than emulating a complete guest machine"},{"id":"tech2-47","category":"database_technical","subcategory":"Concurrency","question_text":"What is a race condition?","options":["Behavior depending unexpectedly on the timing of concurrent operations","A sorted database query","A password policy","A network address"],"correct_answer":"A","explanation":"Race conditions arise when unsynchronized operations access shared state.","estimated_time_seconds":60,"difficulty":2,"option_a":"Behavior depending unexpectedly on the timing of concurrent operations","option_b":"A sorted database query","option_c":"A password policy","option_d":"A network address"},{"id":"tech2-48","category":"database_technical","subcategory":"Concurrency","question_text":"What is a deadlock?","options":["A successful transaction","Tasks waiting indefinitely for resources held by one another","A completed HTTP request","A balanced search tree"],"correct_answer":"B","explanation":"Deadlock is a cycle of waits with no participant able to proceed.","estimated_time_seconds":60,"difficulty":3,"option_a":"A successful transaction","option_b":"Tasks waiting indefinitely for resources held by one another","option_c":"A completed HTTP request","option_d":"A balanced search tree"},{"id":"tech2-49","category":"database_technical","subcategory":"Data","question_text":"What is data validation?","options":["Deleting every incomplete record","Turning text into an image","Checking that input satisfies defined rules before use","Publishing credentials"],"correct_answer":"C","explanation":"Validation rejects or reports data that violates expected constraints.","estimated_time_seconds":60,"difficulty":3,"option_a":"Deleting every incomplete record","option_b":"Turning text into an image","option_c":"Checking that input satisfies defined rules before use","option_d":"Publishing credentials"},{"id":"tech2-50","category":"database_technical","subcategory":"Data","question_text":"Why are backups tested through restore exercises?","options":["To increase query latency","To expose secrets","To replace access control","To verify that data can actually be recovered"],"correct_answer":"D","explanation":"A backup is useful only if it can be restored correctly when needed.","estimated_time_seconds":60,"difficulty":3,"option_a":"To increase query latency","option_b":"To expose secrets","option_c":"To replace access control","option_d":"To verify that data can actually be recovered"}]$diagnostic$::jsonb) as x(id text,question_text text,category text,subcategory text,difficulty numeric,option_a text,option_b text,option_c text,option_d text,correct_answer char(1),explanation text,estimated_time_seconds integer) on conflict(id) do update set question_text=excluded.question_text,category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,option_a=excluded.option_a,option_b=excluded.option_b,option_c=excluded.option_c,option_d=excluded.option_d,correct_answer=excluded.correct_answer,explanation=excluded.explanation,estimated_time_seconds=excluded.estimated_time_seconds,active=true;
